// Boxing: value type to reference type
int number = 42; // stored on stack
object boxed = number; // stored on heap

// Unboxing: reference type to value type
try {
    int unboxed = (int)boxed; // explicit cast required
    Console.WriteLine(unboxed); // 42
} catch (InvalidCastException) {
    Console.WriteLine("Invalid cast");
}

// BAD: Boxing in collections (pre-generics)
ArrayList list = new ArrayList();
list.Add(1); // boxing
list.Add(2); // boxing
list.Add(3); // boxing
foreach (int i in list) {
    Console.WriteLine(i); // unboxing each time
}

// GOOD: Generics avoid boxing
List<int> genericList = new List<int>();
genericList.Add(1); // no boxing
genericList.Add(2); // no boxing
genericList.Add(3); // no boxing
foreach (int i in genericList) {
    Console.WriteLine(i); // no unboxing
}
